-- ----------------------------------------------------------------------------
-- Venues: Table: Venues
-- ----------------------------------------------------------------------------
CREATE TABLE venues (
  venue_id                            TEXT                 PRIMARY KEY,         -- Unique venue identifier (slug)
  location                            TEXT                ,                     -- Physical location/address
  capacity                            INTEGER                                   -- Total seating capacity
);
COMMENT ON TABLE venues IS 'Table: Venues';
COMMENT ON COLUMN venues.venue_id IS 'Unique venue identifier (slug)';
COMMENT ON COLUMN venues.location IS 'Physical location/address';
COMMENT ON COLUMN venues.capacity IS 'Total seating capacity';

-- ----------------------------------------------------------------------------
-- Speakers: Table: Speakers
-- ----------------------------------------------------------------------------
CREATE TABLE speakers (
  speaker_id                          TEXT                 PRIMARY KEY,         -- Unique speaker identifier (email)
  availability_start                  TIMESTAMPTZ         ,                     -- Start of speaker availability window
  availability_end                    TIMESTAMPTZ                               -- End of speaker availability window
);
COMMENT ON TABLE speakers IS 'Table: Speakers';
COMMENT ON COLUMN speakers.speaker_id IS 'Unique speaker identifier (email)';
COMMENT ON COLUMN speakers.availability_start IS 'Start of speaker availability window';
COMMENT ON COLUMN speakers.availability_end IS 'End of speaker availability window';

-- ----------------------------------------------------------------------------
-- Events: Table: Events
-- ----------------------------------------------------------------------------
CREATE TABLE events (
  event_id                            TEXT                 PRIMARY KEY,         -- Unique event identifier
  venue                               TEXT                ,                     -- Related venue
  event_date                          TIMESTAMPTZ         ,                     -- Event date and start time
  duration_minutes                    INTEGER             ,                     -- Event duration in minutes
  category                            TEXT                ,                     -- Event category or track (e.g. Tech, Community, Learning)
  registration_close_days_before_event INTEGER                                  -- Number of days before the event that registration closes
);
COMMENT ON TABLE events IS 'Table: Events';
COMMENT ON COLUMN events.event_id IS 'Unique event identifier';
COMMENT ON COLUMN events.venue IS 'Related venue';
COMMENT ON COLUMN events.event_date IS 'Event date and start time';
COMMENT ON COLUMN events.duration_minutes IS 'Event duration in minutes';
COMMENT ON COLUMN events.category IS 'Event category or track (e.g. Tech, Community, Learning)';
COMMENT ON COLUMN events.registration_close_days_before_event IS 'Number of days before the event that registration closes';

-- ----------------------------------------------------------------------------
-- Assignments: Table: Assignments (many-to-many: Events to Speakers)
-- ----------------------------------------------------------------------------
CREATE TABLE assignments (
  assignment_id                       TEXT                 PRIMARY KEY,         -- Unique assignment identifier
  event_ref                           TEXT                ,                     -- Related event
  speaker_ref                         TEXT                                      -- Related speaker
);
COMMENT ON TABLE assignments IS 'Table: Assignments (many-to-many: Events to Speakers)';
COMMENT ON COLUMN assignments.assignment_id IS 'Unique assignment identifier';
COMMENT ON COLUMN assignments.event_ref IS 'Related event';
COMMENT ON COLUMN assignments.speaker_ref IS 'Related speaker';

-- ----------------------------------------------------------------------------
-- Attendees: Table: Attendees
-- ----------------------------------------------------------------------------
CREATE TABLE attendees (
  attendee_id                         TEXT                 PRIMARY KEY          -- Unique attendee identifier (email)
);
COMMENT ON TABLE attendees IS 'Table: Attendees';
COMMENT ON COLUMN attendees.attendee_id IS 'Unique attendee identifier (email)';

-- ----------------------------------------------------------------------------
-- RSVPs: Table: RSVPs (many-to-many: Events to Attendees)
-- ----------------------------------------------------------------------------
CREATE TABLE rsvps (
  rsvp_id                             TEXT                 PRIMARY KEY,         -- Unique RSVP identifier
  event_ref                           TEXT                ,                     -- Related event
  attendee_ref                        TEXT                ,                     -- Related attendee
  status                              TEXT                                      -- RSVP status (confirmed, waitlist, declined)
);
COMMENT ON TABLE rsvps IS 'Table: RSVPs (many-to-many: Events to Attendees)';
COMMENT ON COLUMN rsvps.rsvp_id IS 'Unique RSVP identifier';
COMMENT ON COLUMN rsvps.event_ref IS 'Related event';
COMMENT ON COLUMN rsvps.attendee_ref IS 'Related attendee';
COMMENT ON COLUMN rsvps.status IS 'RSVP status (confirmed, waitlist, declined)';

